以下是使用C语言实现生产者消费者模型的示例代码：

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define BUFFER_SIZE 10

int buffer[BUFFER_SIZE];
int write_pointer = 0;
int read_pointer = 0;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void *producer(void *arg) {
  while (1) {
    pthread_mutex_lock(&buffer_mutex);

    while ((write_pointer + 1) % BUFFER_SIZE == read_pointer) {
      pthread_cond_wait(&not_full, &buffer_mutex);
    }

    buffer[write_pointer] = rand() % 100;
    printf("Producer: inserted %d at position %d\n", buffer[write_pointer], write_pointer);
    write_pointer = (write_pointer + 1) % BUFFER_SIZE;

    pthread_cond_signal(&not_empty);
    pthread_mutex_unlock(&buffer_mutex);
  }
}

void *consumer(void *arg) {
  while (1) {
    pthread_mutex_lock(&buffer_mutex);

    while (write_pointer == read_pointer) {
      pthread_cond_wait(&not_empty, &buffer_mutex);
    }

    int data = buffer[read_pointer];
    printf("Consumer: retrieved %d from position %d\n", data, read_pointer);
    read_pointer = (read_pointer + 1) % BUFFER_SIZE;

    pthread_cond_signal(&not_full);
    pthread_mutex_unlock(&buffer_mutex);
  }
}

int main() {
  pthread_t producer_thread, consumer_thread;
  srand(time(NULL));

  pthread_create(&producer_thread, NULL, producer, NULL);
  pthread_create(&consumer_thread, NULL, consumer, NULL);

  pthread_join(producer_thread, NULL);
  pthread_join(consumer_thread, NULL);

  return 0;
}
```

在这个示例中，我们使用了一个固定大小的循环缓冲区来存储数据。生产者线程会产生一个随机整数并将其写入缓冲区，而消费者线程则从缓冲区读取数据。通过使用互斥锁和条件变量，我们确保了在缓冲区满时生产者进入等待状态，以及在缓冲区空时消费者进入等待状态。生产者和消费者在缓冲区有空间或数据时被唤醒，并会相应地释放和获取互斥锁以进行同步。

