fn main() {
    // Set the log level to trace for all available logging output
    Env::default().filter_or("MY_APP_LOG", "trace").init();

    trace!("This is a trace message."); // Lowest level - provides the most detailed output
    debug!("This is a debug message.");
    info!("This is an informational message.");
    warn!("This is a warning message.");
    error!("This is an error message."); // Highest level - used for significant errors
}
```

