# 牛顿迭代法
import math

r = 10/100   # 球体半径
ρ = 0.638   # 球体密度
ρw = 1.0    # 水的密度
s = ρ/ρw   # 球体材料的比重

def f(h):
    return (math.pi/3)*(3*r*h**2 - h**3) - s*4/3*math.pi*r**3*h

def f_derivative(h):
    return math.pi*(3*r**2 - 3*h**2)

